        "text": "تجلس سلمى مع آدم في الشرفة. لا يتحدثان عن السنوات كلها؛ يتحدثان عن لعبة خشبية، وعن شجرة كانت قرب المستشفى، وعن أغنية نسيا كلماتها. في نهاية اللقاء تقول سلمى إنها لا تعرف إن كانت ستراه غدًا، لكنها لا تمانع أن يرسل رسالة. أحيانًا تكون البداية أصغر من النهاية التي تخيلناها.",
