        "text": "تستمع مريم إلى شهادتك حتى النهاية. لا تقاطعك ولا تقول إنها سامحتك. فقط تسأل: «هل ستكتب ما رأيته كما حدث، حتى لو لم يجعلك بطلًا؟». حين توافق، تعطيك آخر صفحة من دفترها. فيها أسماء الأطفال السبعة، وأمام كل اسم علامة خروج. لا توجد علامة بجوار اسم سلمى، بل كلمة واحدة: «اختيرت».",
