        "text": "يرد الصوت بعد دقيقة. يقول إنه مراد، لكنه لا يستطيع إثبات ذلك من خلال الهاتف وحده. يصف الصورة التي يحملها محمود: بقعة حبر قرب كتف الطفل، وقطعًا في زاوية الإطار. محمود ينهار للحظة ثم يستعيد صوته. يطلب مراد ألا ينزل أحد قبل تثبيت الحبل؛ جزء من الممر انهار، والهواء قليل. هالة تفحص جهاز التنفس وتقول إن اسطوانته تكفي لشخص واحد لفترة قصيرة. الآن لم يعد السؤال هل يوجد أحد هناك، بل كيف تصلون إليه دون أن تفقدوا شخصًا آخر.\n\nيطلب مراد منكم وصف عدد الموجودين في الخارج، ثم يصحح سامح العدد مرتين. يرفض مراد الإجابة عن سؤال محمود قبل أن يسمع أسماء الركاب الحاليين. يبدو أنه لا يختبر هويتكم، بل يتأكد أن أحدًا لن يكرر الخطأ نفسه ويغادر قبل العدّ.",
