        "text": "تصلون إلى غرفة جانبية ضيقة. مراد موجود، مصاب في ساقه لكنه واعٍ. بجانبه صندوق أدوات وسجل ورقي يوضح أنه عاش في غرفة الصيانة بعد انهيار الممر، وكان يخرج أحيانًا لترك إشارات تحذير. لم يكن ينتظر أن يعيد الطريق الماضي حرفيًا؛ كان يحاول منع حادث جديد. يخبركم أن الضوء الأحمر إشارة تحذير لمجرى السيول، وأن الوميض المتكرر كان آخر وسيلة لديه لجذب انتباه أي مركبة تمر. فجأة يسمع صوت تشقق فوقكم. لا يمكن إخراج مراد بالطريقة نفسها التي دخلتم بها.\n\nيرفض مراد أن يتحرك قبل أن يسمع تأكيدًا بأن الحبل مثبت من جهتين. يشرح أن الممر تغير بعد آخر موجة مطر، وأن جزءًا من السقف صار معلقًا على طبقة طينية. لا يتصرف كبطل خارق؛ إنه يعرف المكان جيدًا، لكنه يعرف أيضًا حدود قدرته.",
